if (msg.type === "user") {
  const content = (msg as { message?: { content?: string } }).message?.content ?? "";
  return {
    id: nextId(),
    role: "user",
    content,
    timestamp: Date.now(),
  };
}

input.new_string:
if (msg.type === "user") {
  const rawContent = (msg as { message?: { content?: unknown } }).message?.content ?? "";
  // content can be a plain string or an array of content blocks
  let content: string;
  if (typeof rawContent === "string") {
    content = rawContent;
  } else if (Array.isArray(rawContent)) {
    content = rawContent
      .map((b: { type?: string; text?: string; content?: unknown; tool_use_id?: string }) => {
        if (b.type === "text") return b.text ?? "";
        if (b.type === "tool_result") {
          const inner = typeof b.content === "string" ? b.content : JSON.stringify(b.content);
          return `[tool_result: ${inner}]`;
        }
        return "";
      })
      .filter(Boolean)
      .join("\n");
  } else {
    content = String(rawContent);
  }
  return {
    id: nextId(),
    role: "user",
    content,
    timestamp: Date.now(),
  };
}

if (b.type === "tool_result") {
  const c = (b as { content?: unknown }).content;
  return `[tool_result: ${typeof c === "string" ? c : JSON.stringify(c)}]`;
}

