"use client";

/**
 * Single chat message bubble.
 * - **user** — right-aligned, primary background.
 * - **assistant** — left-aligned, secondary background.
 * - **system** — centered, italic, muted (used for init info, result summaries, errors).
 */

import type { ChatMessage } from "@/lib/types";
import { cn } from "@/lib/utils";

export function Message({ message }: { message: ChatMessage }) {
  if (message.role === "system") {
    return (
      <div className="py-1 text-center text-xs italic text-muted-foreground">
        {message.content}
      </div>
    );
  }

  const isUser = message.role === "user";

  return (
    <div className={cn("flex", isUser ? "justify-end" : "justify-start")}>
      <div
        className={cn(
          "max-w-[90%] md:max-w-[80%] rounded-lg px-3 py-2 text-sm whitespace-pre-wrap",
          isUser
            ? "bg-primary text-primary-foreground"
            : "bg-secondary text-secondary-foreground"
        )}
      >
        {message.content}
      </div>
    </div>
  );
}

content.content:
  1→"use client";
  2→
  3→/**
  4→ * React hook that manages the WebSocket connection to the thos relay server.
  5→ *
  6→ * Supports multiple concurrent agents. Each agent has its own status,
  7→ * message history, label, and tmux session name tracked in a Map keyed
  8→ * by agent ID. The `activeAgentId` determines which agent's chat is shown.
  9→ *
 10→ * ## Connection lifecycle
 11→ *
 12→ * 1. Connect to `ws://<host>:9900/browser`.
 13→ * 2. Server sends `agent_list` (sidebar metadata) + `task_list`. No
 14→ *    message histories are sent eagerly — this keeps the initial
 15→ *    payload small for fast loading on mobile networks.
 16→ * 3. `initialLoadDone` becomes true after `agent_list` arrives.
 17→ * 4. The first agent is auto-selected if nothing was selected.
 18→ *
 19→ * ## Lazy history loading
 20→ *
 21→ * Message histories are loaded on demand. When `activeAgentId` changes
 22→ * and the agent hasn't been loaded yet, the hook sends
 23→ * `{ type: "request_history", agentId }` and sets `historyLoading = true`.
 24→ * When the server responds with `message_history`, the agent's messages
 25→ * are populated and `historyLoading` becomes false.
 26→ *
 27→ * The `loadedAgents` Set tracks which agents have been fetched so that
 28→ * switching back to a previously viewed agent is instant.
 29→ *
 30→ * ## Resilience features
 31→ *
 32→ * - Handles `message_history` replay from server on demand.
 33→ * - Handles `cli_disconnected` / `cli_connected` events.
 34→ * - Deduplicates messages using a per-agent processed count.
 35→ * - Robust reconnection guard (clears previous timer before scheduling).
 36→ * - Strict mode safe (closingRef prevents spurious reconnects on unmount).
 37→ *
 38→ * ## Logging
 39→ *
 40→ * All WS events are logged with the `[thos-ws]` prefix. Filter by this
 41→ * in the browser console to debug connection and message delivery issues.
 42→ */
 43→
 44→import { useCallback, useEffect, useMemo, useRef, useState } from "react";
 45→import type {
 46→  AgentInfo,
 47→  AgentStatus,
 48→  ChatMessage,
 49→  ClaudeAssistant,
 50→  ClaudeControlRequest,
 51→  ClaudeMessage,
 52→  ClaudeResult,
 53→  ClaudeSystemInit,
 54→  ServerMessage,
 55→  ServerMessageHistory,
 56→  ServerTaskList,
 57→  ServerTaskUpdated,
 58→  ServerTaskDeleted,
 59→  Task,
 60→  TaskPriority,
 61→  ToolCallInfo,
 62→  UserQuestion,
 63→} from "@/lib/types";
 64→
 65→/** Connect to the WS server on the same host the page was loaded from. */
 66→const WS_URL =
 67→  typeof window !== "undefined"
 68→    ? `ws://${window.location.hostname}:9900/browser`
 69→    : "ws://localhost:9900/browser";
 70→
 71→/** Per-agent client state. */
 72→export interface AgentClientState {
 73→  status: AgentStatus;
 74→  messages: ChatMessage[];
 75→  /** Raw Claude NDJSON messages for debug view. */
 76→  rawMessages: ClaudeMessage[];
 77→  label: string;
 78→  tmuxSession: string | null;
 79→  createdAt: number;
 80→}
 81→
 82→/**
 83→ * Extract displayable text from a Claude assistant message.
 84→ * Content blocks may be text, tool_use, or tool_result — each is
 85→ * handled defensively since the array structure can vary.
 86→ */
 87→function extractText(msg: ClaudeAssistant): string {
 88→  const blocks = msg.message?.content;
 89→  if (!blocks || !Array.isArray(blocks)) return "";
 90→  return blocks
 91→    .map((b) => {
 92→      if (b.type === "text") return b.text;
 93→      if (b.type === "tool_use") return `[tool_use: ${b.name}]`;
 94→      if (b.type === "tool_result") return `[tool_result: ${b.content}]`;
 95→      return "";
 96→    })
 97→    .filter(Boolean)
 98→    .join("\n");
 99→}
100→
101→/** Module-level counter for generating unique message IDs. */
102→let msgCounter = 0;
103→function nextId() {
104→  return `msg-${Date.now()}-${++msgCounter}`;
105→}
106→
107→/**
108→ * Convert a server relay message into a ChatMessage, or null if it shouldn't be displayed.
109→ * Used both for live messages and for replaying message_history.
110→ */
111→function relayChatMessage(agentId: string, relayMsg: ServerMessage): ChatMessage | null {
112→  if (relayMsg.type === "relay") {
113→    const msg = relayMsg.message;
114→
115→    if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
116→      const init = msg as ClaudeSystemInit;
117→      return {
118→        id: nextId(),
119→        role: "system",
120→        content: `Session started — model: ${init.model}, cwd: ${init.cwd}`,
121→        timestamp: Date.now(),
122→      };
123→    }
124→
125→    if (msg.type === "user") {
126→      const content = (msg as { message?: { content?: string } }).message?.content ?? "";
127→      return {
128→        id: nextId(),
129→        role: "user",
130→        content,
131→        timestamp: Date.now(),
132→      };
133→    }
134→
135→    if (msg.type === "assistant") {
136→      const assistant = msg as ClaudeAssistant;
137→      const text = extractText(assistant);
138→      if (!text) return null;
139→
140→      const blocks = assistant.message?.content ?? [];
141→      const hasText = blocks.some((b) => b.type === "text" && b.text.trim());
142→      const toolCalls: ToolCallInfo[] = blocks
143→        .filter((b) => b.type === "tool_use")
144→        .map((b) => ({
145→          name: (b as { name: string }).name,
146→          toolUseId: (b as { id: string }).id,
147→        }));
148→      const isToolOnly = !hasText && toolCalls.length > 0;
149→
150→      return {
151→        id: nextId(),
152→        role: "assistant",
153→        content: text,
154→        timestamp: Date.now(),
155→        toolCalls,
156→        isToolOnly,
157→      };
158→    }
159→
160→    if (msg.type === "result") {
161→      const result = msg as ClaudeResult;
162→      const summary = result.is_error
163→        ? `Error: ${result.error}`
164→        : `Done — ${result.num_turns ?? "?"} turns, $${(result.cost_usd ?? 0).toFixed(4)}, ${((result.duration_ms ?? 0) / 1000).toFixed(1)}s`;
165→      return {
166→        id: nextId(),
167→        role: "system",
168→        content: summary,
169→        timestamp: Date.now(),
170→      };
171→    }
172→
173→    if (msg.type === "control_request") {
174→      const cr = msg as ClaudeControlRequest;
175→
176→      // AskUserQuestion gets its own UI instead of generic Allow/Deny
177→      if (cr.request.tool_name === "AskUserQuestion") {
178→        const input = cr.request.input as { questions?: UserQuestion[] };
179→        const questions = Array.isArray(input.questions) ? input.questions : [];
180→        return {
181→          id: nextId(),
182→          role: "system",
183→          content: "Question from Claude",
184→          timestamp: Date.now(),
185→          userQuestion: {
186→            requestId: cr.request_id,
187→            questions,
188→          },
189→        };
190→      }
191→
192→      return {
193→        id: nextId(),
194→        role: "system",
195→        content: `Tool approval requested: ${cr.request.tool_name}`,
196→        timestamp: Date.now(),
197→        controlRequest: {
198→          id: cr.request_id,
199→          tool_name: cr.request.tool_name,
200→          input: cr.request.input,
201→        },
202→      };
203→    }
204→  }
205→
206→  if (relayMsg.type === "error" && relayMsg.agentId === agentId) {
207→    return {
208→      id: nextId(),
209→      role: "system",
210→      content: `Error: ${relayMsg.error}`,
211→      timestamp: Date.now(),
212→    };
213→  }
214→
215→  return null;
216→}
217→
218→/** Console logger with [thos] prefix for easy filtering. */
219→function log(...args: unknown[]) {
220→  console.log("[thos-ws]", ...args);
221→}
222→
223→export function useWebSocket() {
224→  const wsRef = useRef<WebSocket | null>(null);
225→  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
226→  /** Set to true during cleanup to prevent onclose from scheduling reconnects. */
227→  const closingRef = useRef(false);
228→  const [connected, setConnected] = useState(false);
229→  /** True once we've received the initial agent_list from the server. */
230→  const [initialLoadDone, setInitialLoadDone] = useState(false);
231→
232→  // Multi-agent state
233→  const [agents, setAgents] = useState<Map<string, AgentClientState>>(new Map());
234→  const [agentOrder, setAgentOrder] = useState<string[]>([]);
235→  const [activeAgentId, setActiveAgentId] = useState<string | null>(null);
236→
237→  // Task state
238→  const [tasks, setTasks] = useState<Task[]>([]);
239→
240→  // Per-agent deduplication: track count of processed messages per agent
241→  // to avoid duplicating messages already in local state during history replay.
242→  const processedCountRef = useRef<Map<string, number>>(new Map());
243→
244→  // Track which agents have had their history loaded (lazy loading).
245→  const [loadedAgents, setLoadedAgents] = useState<Set<string>>(new Set());
246→
247→  /** Immutably update a single agent's state in the Map. */
248→  const updateAgent = useCallback(
249→    (agentId: string, updater: (prev: AgentClientState) => AgentClientState) => {
250→      setAgents((prev) => {
251→        const existing = prev.get(agentId);
252→        if (!existing) return prev;
253→        const next = new Map(prev);
254→        next.set(agentId, updater(existing));
255→        return next;
256→      });
257→    },
258→    []
259→  );
260→
261→  const connect = useCallback(() => {
262→    if (wsRef.current?.readyState === WebSocket.OPEN) return;
263→    if (wsRef.current) {
264→      wsRef.current.close();
265→      wsRef.current = null;
266→    }
267→
268→    // Reset dedup counts on new connection — server will send fresh history
269→    processedCountRef.current.clear();
270→    setInitialLoadDone(false);
271→    setLoadedAgents(new Set());
272→
273→    log("connecting to", WS_URL);
274→    const ws = new WebSocket(WS_URL);
275→    wsRef.current = ws;
276→
277→    ws.onopen = () => {
278→      log("connected");
279→      setConnected(true);
280→    };
281→
282→    ws.onclose = () => {
283→      log("disconnected, closingRef =", closingRef.current);
284→      setConnected(false);
285→      wsRef.current = null;
286→      // Don't reconnect if the close was triggered by cleanup (e.g. strict mode unmount)
287→      if (closingRef.current) return;
288→      // Reconnection guard: clear any existing timer before scheduling
289→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
290→      log("scheduling reconnect in 2s");
291→      reconnectTimer.current = setTimeout(() => connect(), 2000);
292→    };
293→
294→    ws.onerror = (e) => {
295→      log("error", e);
296→      // onclose will fire after onerror, which triggers reconnect
297→    };
298→
299→    ws.onmessage = (event) => {
300→      let data: ServerMessage;
301→      try {
302→        data = JSON.parse(event.data as string);
303→      } catch {
304→        return;
305→      }
306→
307→      log("←", data.type, "agentId" in data ? (data as { agentId: string }).agentId : "");
308→
309→      // ── task_list: full task list from server ──
310→      if (data.type === "task_list") {
311→        log("task_list:", (data as ServerTaskList).tasks.length, "tasks");
312→        setTasks((data as ServerTaskList).tasks);
313→        return;
314→      }
315→
316→      // ── task_updated: single task changed ──
317→      if (data.type === "task_updated") {
318→        const updated = (data as ServerTaskUpdated).task;
319→        setTasks((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
320→        return;
321→      }
322→
323→      // ── task_deleted: remove task ──
324→      if (data.type === "task_deleted") {
325→        const deletedId = (data as ServerTaskDeleted).taskId;
326→        setTasks((prev) => prev.filter((t) => t.id !== deletedId));
327→        return;
328→      }
329→
330→      // ── message_history: replay full history from server ──
331→      if (data.type === "message_history") {
332→        const historyMsg = data as ServerMessageHistory;
333→        const agentId = historyMsg.agentId;
334→        const serverMessages = historyMsg.messages;
335→        log("message_history:", agentId, serverMessages.length, "raw msgs");
336→
337→        // Convert all server messages to ChatMessages + extract raw Claude messages
338→        const chatMessages: ChatMessage[] = [];
339→        const rawMessages: ClaudeMessage[] = [];
340→        for (const sm of serverMessages) {
341→          if (sm.type === "relay") {
342→            rawMessages.push(sm.message);
343→          }
344→          const cm = relayChatMessage(agentId, sm);
345→          if (cm) chatMessages.push(cm);
346→        }
347→        log("message_history:", agentId, "→", chatMessages.length, "chat msgs,", rawMessages.length, "raw");
348→
349→        // Always replace local messages with server history (source of truth).
350→        setAgents((prev) => {
351→          const existing = prev.get(agentId);
352→          if (!existing) {
353→            log("message_history:", agentId, "agent not in map yet, creating");
354→            const next = new Map(prev);
355→            next.set(agentId, {
356→              status: "idle",
357→              messages: chatMessages,
358→              rawMessages,
359→              label: "",
360→              tmuxSession: null,
361→              createdAt: 0,
362→            });
363→            return next;
364→          }
365→          const next = new Map(prev);
366→          next.set(agentId, { ...existing, messages: chatMessages, rawMessages });
367→          return next;
368→        });
369→
370→        processedCountRef.current.set(agentId, chatMessages.length);
371→        setLoadedAgents((prev) => {
372→          if (prev.has(agentId)) return prev;
373→          const next = new Set(prev);
374→          next.add(agentId);
375→          return next;
376→        });
377→        return;
378→      }
379→
380→      // ── history_cleared: wipe local messages for this agent ──
381→      if (data.type === "history_cleared") {
382→        updateAgent(data.agentId, (prev) => ({
383→          ...prev,
384→          messages: [],
385→          rawMessages: [],
386→        }));
387→        processedCountRef.current.set(data.agentId, 0);
388→        return;
389→      }
390→
391→      // ── cli_disconnected: show system message ──
392→      if (data.type === "cli_disconnected") {
393→        updateAgent(data.agentId, (prev) => ({
394→          ...prev,
395→          messages: [
396→            ...prev.messages,
397→            {
398→              id: nextId(),
399→              role: "system",
400→              content: "CLI session ended",
401→              timestamp: Date.now(),
402→            },
403→          ],
404→        }));
405→        return;
406→      }
407→
408→      // ── cli_connected: show system message ──
409→      if (data.type === "cli_connected") {
410→        updateAgent(data.agentId, (prev) => ({
411→          ...prev,
412→          messages: [
413→            ...prev.messages,
414→            {
415→              id: nextId(),
416→              role: "system",
417→              content: "CLI reconnected",
418→              timestamp: Date.now(),
419→            },
420→          ],
421→        }));
422→        return;
423→      }
424→
425→      // ── agent_list: reconcile sidebar state from server ──
426→      if (data.type === "agent_list") {
427→        const serverAgents = data.agents as AgentInfo[];
428→        log("agent_list:", serverAgents.length, "agents:", serverAgents.map((a) => `${a.agentId}(${a.status})`).join(", "));
429→        setAgents((prev) => {
430→          const next = new Map(prev);
431→          const serverIds = new Set(serverAgents.map((a) => a.agentId));
432→
433→          // Update or add agents from server
434→          for (const info of serverAgents) {
435→            const existing = next.get(info.agentId);
436→            if (existing) {
437→              next.set(info.agentId, {
438→                ...existing,
439→                status: info.status,
440→                tmuxSession: info.tmuxSession,
441→                label: info.label,
442→              });
443→            } else {
444→              next.set(info.agentId, {
445→                status: info.status,
446→                messages: [],
447→                rawMessages: [],
448→                label: info.label,
449→                tmuxSession: info.tmuxSession,
450→                createdAt: info.createdAt,
451→              });
452→            }
453→          }
454→
455→          // Remove agents no longer on the server
456→          for (const id of next.keys()) {
457→            if (!serverIds.has(id)) {
458→              next.delete(id);
459→            }
460→          }
461→
462→          return next;
463→        });
464→        setAgentOrder(serverAgents.map((a) => a.agentId));
465→        setInitialLoadDone(true);
466→
467→        // Auto-select the first agent on initial load when nothing is selected
468→        setActiveAgentId((prev) => {
469→          if (prev !== null) return prev;
470→          if (serverAgents.length === 0) return null;
471→          return serverAgents[0].agentId;
472→        });
473→        return;
474→      }
475→
476→      // ── spawned: auto-select the newly created agent ──
477→      if (data.type === "spawned") {
478→        setActiveAgentId(data.agentId);
479→        return;
480→      }
481→
482→      // ── status: update a specific agent's status ──
483→      if (data.type === "status") {
484→        updateAgent(data.agentId, (prev) => ({ ...prev, status: data.status }));
485→        return;
486→      }
487→
488→      // ── error: append to agent's message list ──
489→      if (data.type === "error") {
490→        updateAgent(data.agentId, (prev) => ({
491→          ...prev,
492→          messages: [
493→            ...prev.messages,
494→            {
495→              id: nextId(),
496→              role: "system",
497→              content: `Error: ${data.error}`,
498→              timestamp: Date.now(),
499→            },
500→          ],
501→        }));
502→        // Track processed count for dedup
503→        processedCountRef.current.set(
504→          data.agentId,
505→          (processedCountRef.current.get(data.agentId) ?? 0) + 1
506→        );
507→        return;
508→      }
509→
510→      // ── relay: append claude message to agent's history ──
511→      if (data.type === "relay") {
512→        const agentId = data.agentId;
513→        const rawMsg = data.message;
514→        const chatMsg = relayChatMessage(agentId, data);
515→
516→        updateAgent(agentId, (prev) => ({
517→          ...prev,
518→          rawMessages: [...prev.rawMessages, rawMsg],
519→          messages: chatMsg ? [...prev.messages, chatMsg] : prev.messages,
520→        }));
521→        if (chatMsg) {
522→          // Track processed count for dedup
523→          processedCountRef.current.set(
524→            agentId,
525→            (processedCountRef.current.get(agentId) ?? 0) + 1
526→          );
527→        }
528→        return;
529→      }
530→    };
531→  }, [updateAgent]);
532→
533→  useEffect(() => {
534→    closingRef.current = false;
535→    connect();
536→    return () => {
537→      closingRef.current = true;
538→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
539→      wsRef.current?.close();
540→    };
541→  }, [connect]);
542→
543→  const send = useCallback((data: object) => {
544→    if (wsRef.current?.readyState === WebSocket.OPEN) {
545→      wsRef.current.send(JSON.stringify(data));
546→    }
547→  }, []);
548→
549→  // Request history for the active agent if not already loaded.
550→  useEffect(() => {
551→    if (!activeAgentId || loadedAgents.has(activeAgentId)) return;
552→    log("requesting history for", activeAgentId);
553→    send({ type: "request_history", agentId: activeAgentId });
554→  }, [activeAgentId, loadedAgents, send]);
555→
556→  const spawnAgent = useCallback(
557→    (prompt: string) => {
558→      send({ type: "spawn", prompt });
559→    },
560→    [send]
561→  );
562→
563→  const sendMessage = useCallback(
564→    (content: string) => {
565→      if (!activeAgentId) return;
566→      // Optimistically add user message to local state
567→      updateAgent(activeAgentId, (prev) => ({
568→        ...prev,
569→        messages: [
570→          ...prev.messages,
571→          {
572→            id: nextId(),
573→            role: "user",
574→            content,
575→            timestamp: Date.now(),
576→          },
577→        ],
578→      }));
579→      send({ type: "send_message", agentId: activeAgentId, content });
580→    },
581→    [send, activeAgentId, updateAgent]
582→  );
583→
584→  const respondToControl = useCallback(
585→    (requestId: string, allow: boolean) => {
586→      if (!activeAgentId) return;
587→      send({ type: "control_response", agentId: activeAgentId, request_id: requestId, allow });
588→      updateAgent(activeAgentId, (prev) => ({
589→        ...prev,
590→        messages: prev.messages.map((m) =>
591→          m.controlRequest?.id === requestId
592→            ? { ...m, controlRequest: { ...m.controlRequest, resolved: true } }
593→            : m
594→        ),
595→      }));
596→    },
597→    [send, activeAgentId, updateAgent]
598→  );
599→
600→  /** Respond to an AskUserQuestion control request with the user's selections. */
601→  const respondToUserQuestion = useCallback(
602→    (requestId: string, answers: Record<string, string>) => {
603→      if (!activeAgentId) return;
604→      send({
605→        type: "control_response",
606→        agentId: activeAgentId,
607→        request_id: requestId,
608→        allow: true,
609→        answers,
610→      });
611→      updateAgent(activeAgentId, (prev) => ({
612→        ...prev,
613→        messages: prev.messages.map((m) =>
614→          m.userQuestion?.requestId === requestId
615→            ? { ...m, userQuestion: { ...m.userQuestion, resolved: true } }
616→            : m
617→        ),
618→      }));
619→    },
620→    [send, activeAgentId, updateAgent]
621→  );
622→
623→  // ── Agent management actions ──────────────────────────────────────────────
624→
625→  const killAgent = useCallback(
626→    (agentId: string) => {
627→      send({ type: "kill_agent", agentId });
628→    },
629→    [send]
630→  );
631→
632→  const deleteAgent = useCallback(
633→    (agentId: string) => {
634→      send({ type: "delete_agent", agentId });
635→      // Deselect if we just deleted the active agent
636→      setActiveAgentId((prev) => (prev === agentId ? null : prev));
637→    },
638→    [send]
639→  );
640→
641→  const renameAgent = useCallback(
642→    (agentId: string, label: string) => {
643→      send({ type: "rename_agent", agentId, label });
644→    },
645→    [send]
646→  );
647→
648→  const clearHistory = useCallback(
649→    (agentId: string) => {
650→      send({ type: "clear_history", agentId });
651→    },
652→    [send]
653→  );
654→
655→  // ── Task actions ──────────────────────────────────────────────────────────
656→
657→  const createTask = useCallback(
658→    (title: string, description: string, priority: TaskPriority) => {
659→      send({ type: "create_task", title, description, priority });
660→    },
661→    [send]
662→  );
663→
664→  const updateTask = useCallback(
665→    (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => {
666→      send({ type: "update_task", taskId, updates });
667→    },
668→    [send]
669→  );
670→
671→  const deleteTask = useCallback(
672→    (taskId: string) => {
673→      send({ type: "delete_task", taskId });
674→    },
675→    [send]
676→  );
677→
678→  const delegateTask = useCallback(
679→    (taskId: string) => {
680→      send({ type: "delegate_task", taskId });
681→    },
682→    [send]
683→  );
684→
685→  // Derived values for the active agent
686→  const activeAgent = activeAgentId ? agents.get(activeAgentId) : undefined;
687→  const activeStatus = useMemo<AgentStatus>(
688→    () => activeAgent?.status ?? "idle",
689→    [activeAgent?.status]
690→  );
691→  const activeMessages = useMemo<ChatMessage[]>(
692→    () => activeAgent?.messages ?? [],
693→    [activeAgent?.messages]
694→  );
695→  const activeRawMessages = useMemo<ClaudeMessage[]>(
696→    () => activeAgent?.rawMessages ?? [],
697→    [activeAgent?.rawMessages]
698→  );
699→  const historyLoading = activeAgentId !== null && !loadedAgents.has(activeAgentId);
700→
701→  return {
702→    connected,
703→    initialLoadDone,
704→    historyLoading,
705→    agents,
706→    agentOrder,
707→    activeAgentId,
708→    setActiveAgentId,
709→    activeStatus,
710→    activeMessages,
711→    activeRawMessages,
712→    spawnAgent,
713→    sendMessage,
714→    respondToControl,
715→    respondToUserQuestion,
716→    killAgent,
717→    deleteAgent,
718→    renameAgent,
719→    clearHistory,
720→    tasks,
721→    createTask,
722→    updateTask,
723→    deleteTask,
724→    delegateTask,
725→  };
726→}
